/// <summary>
/// Extension of the class <c>AVAFPLLedgerAllocationRequest</c>
/// </summary>
[ExtensionOf(classStr(AVAFPLLedgerAllocationRequest))]
internal final class AVAFPLLedgerAllocationRequestCls_Extension
{
    static private AVAFPLLedgerAllocationRequest ledgerAllocationRequest_bec;
    private boolean copiedWithDifLayer_bec;
    private boolean postedWithDifLayer_bec;
    private boolean summarizeValues_bec;
    private boolean ruleArc_bec;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        copiedWithDifLayer_bec,
        postedWithDifLayer_bec,
        summarizeValues_bec,
        ruleArc_bec
    #endmacro

}

