/// <summary>
/// Initializes a new <c>LedgerAllocationProcessRequest</c> instance.
/// </summary>
protected void initializeLedgerAllocationProcessRequest()
{
    next initializeLedgerAllocationProcessRequest();
    ledgerAllocationProcessRequest.parmCopiedWithDifLayer_bec(copiedWithDifLayer_bec);
    ledgerAllocationProcessRequest.parmPostedWithDifLayer_bec(postedWithDifLayer_bec);
    ledgerAllocationProcessRequest.parmSummarizeValues_bec(summarizeValues_bec);
    ledgerAllocationProcessRequest.parmRuleArc_bec(ruleArc_bec);
}

/// <summary>
/// Runs the allocation process.
/// </summary>
public void run()
{
    AVAFPLLedgerAllocationRuleGroupDetails  ruleGroupDetails;
    AVAFPLLedgerAllocationRuleGroup         ruleGroup;
    LedgerAllocationRule                    ledgerAllocationRule_bec;

    ledgerAllocationRequest_bec = this;

    if (ruleGroupId && LedgerParameters::find().AVAKoRe)
    {
        select firstonly RuleId from ruleGroupDetails
            order by ledgerAllocationRule_bec.AVASequence desc
            where ruleGroupDetails.RuleGroupId == ruleGroupId
            join AVASequence from ledgerAllocationRule_bec
            where ledgerAllocationRule_bec.RuleId == ruleGroupDetails.RuleId;

        LedgerAllocationRuleID lastRuleId = ruleGroupDetails.RuleId;

        while select RuleId from ruleGroupDetails
            order by ledgerAllocationRule_bec.AVASequence
            where ruleGroupDetails.RuleGroupId == ruleGroupId
            join AVASequence from ledgerAllocationRule_bec
            where ledgerAllocationRule_bec.RuleId == ruleGroupDetails.RuleId
        {
            if (ruleGroupDetails.RuleId == lastRuleId)
            {
                continue;
            }

            try
            {
                ruleId = ruleGroupDetails.RuleId;
                this.runProcessRequest();
            }
            catch
            {
                continue;
            }
        }

        ttsbegin;
        ruleGroup = AVAFPLLedgerAllocationRuleGroup::find(ruleGroupId, true);
        ruleGroup.DateLastRun = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        ruleGroup.doUpdate();
        ttscommit;

        if (ruleArc_bec)
        {
            //ruleGroup.arcRuleGroup_bec(asOfDate);
            ruleArc_bec = false;
            ledgerAllocationProcessRequest.parmRuleArc_bec(ruleArc_bec);
        }

        ruleGroupId = strMin();
        ruleId = lastRuleId;
    }
    next run();
}
